; Sony SIRC 12-bit infrared frame with a 40 kHz carrier; one 12-bit code per host word, acknowledged
; Generated by escgen from protocols/sirc_tx.yaml: edit the table and
; regenerate (python -m escgen), or take this file over by hand.
; Reference: SB-Projects, Sony SIRC Protocol, www.sbprojects.net/knowledge/ir/sirc.php: 40 kHz carrier, 2.4 ms start burst, 0.6 ms spaces, 1.2 / 0.6 ms bursts, 7 command bits then 5 address bits LSB first, frames every 45 ms
; Every edge is a DRIVE event at an absolute deadline; escert certifies it.

.default CTX, 0
.default CLK_KHZ, 25000                ; core clock in kHz
.equ PERIOD, (CLK_KHZ + 20) // 40
.equ T, 24 * PERIOD
.equ GAP, CLK_KHZ * 26
.equ C_PERIOD, PERIOD
.equ C_HIGH, (PERIOD + 1) // 3
.default PIN_IR, 0
.equ P_IR, 1 << PIN_IR

.own  PIN_IR, CTX
.entry CTX, main

main:
    ADDT  16                          ; first deadline after the first commit
    EMIT  P_IR, 0, P_IR               ; idle levels
    ADDT  1
packet:
    POP   r1                          ; one word per packet (waits for the host)
    WAITT                             ; the last packet's final phase has ended
    RDTIME r3
    ADDI  r3, 64
    SETT  r3
    LDLC  (4 * T) // C_PERIOD         ; start: carrier pulses
    CALL  burst
    MOVI  r3, 12                      ; 12 bits, LSB first, each zero or one
bit1:
    SHR   r1, 1                       ; C = the next bit
    JC    one2
    ADDT  T                           ; zero: no change, no event
    LDLC  (T) // C_PERIOD             ; carrier pulses
    CALL  burst
    JMP   next3
one2:
    ADDT  T                           ; one: no change, no event
    LDLC  (2 * T) // C_PERIOD         ; carrier pulses
    CALL  burst
next3:
    MOVI  r0, 1
    SUB   r3, r0                      ; Z after the last bit
    JNZ   bit1
    ADDT  GAP - 64                    ; gap: no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
    MOVI  r3, 1
    PUSH  r3                          ; packet sent
    JMP   packet

; ---- burst: lc carrier pulses from tmr; returns with tmr = start + lc * C_PERIOD
burst:
    EMIT  P_IR, P_IR, P_IR
    ADDT  C_HIGH
    EMIT  P_IR, 0, P_IR
    ADDT  C_PERIOD - C_HIGH
    DJNZ  burst
    RET
